//! i18n strings — port of `strings/__init__.py` (`StringStore`).
//!
//! Locales live as idiomatic Rust in `locales.rs` (generated by
//! `tools/gen_locales.py` from the source YAML — values preserved, format
//! ported). Lookup mirrors Python: requested language, then English, then
//! the `Warning: could not load any string with the key …` message.

use crate::locales;
use std::sync::Arc;

#[derive(Debug, Clone)]
pub struct Strings {
    pub lang: String,
    map: &'static [(&'static str, &'static str)],
    fallback: &'static [(&'static str, &'static str)],
}

fn lookup(map: &[(&'static str, &'static str)], key: &str) -> Option<&'static str> {
    map.binary_search_by(|(k, _)| k.cmp(&key))
        .ok()
        .map(|i| map[i].1)
}

impl Strings {
    pub fn load(lang: &str) -> Arc<Self> {
        let (map, _) = locales::locale(lang).unwrap_or((locales::EN, &locales::EN_META));
        Arc::new(Strings {
            lang: lang.to_string(),
            map,
            fallback: locales::EN,
        })
    }

    /// Mirrors Python `StringStore.get(key)`: lang -> English -> warning text.
    pub fn get(&self, key: &str) -> String {
        lookup(self.map, key)
            .or_else(|| lookup(self.fallback, key))
            .map(|s| s.to_string())
            .unwrap_or_else(|| format!("Warning: could not load any string with the key `{key}`"))
    }

    /// `help_<key>` document prefixed with the command banner (`cmda`),
    /// mirroring Python `StringStore.help_of`.
    pub fn help_of(&self, key: &str) -> Option<String> {
        let doc_key = format!("help_{key}");
        lookup(self.map, &doc_key)
            .or_else(|| lookup(self.fallback, &doc_key))
            .map(|doc| format!("{}{}", self.get("cmda"), doc))
    }
}
